      "path": "lib/index.js",
      "content": "/**\n * dsh-pdf-reader — DeepSeek Harness plugin bundle for content-aware PDF reading\n * by vision models.\n *\n * Registers three model-facing tools (pdf_scan / pdf_read_page /\n * pdf_render_region) backed by a PyMuPDF helper. Theme: read the content the\n * right way — text pages via extraction, figure/table/math pages via a\n * high-DPI region crop fed to read_image — so a two-column paper's vector\n * figures and tables are never lost to the whole-page ~800x800 token ceiling.\n */\nimport { registerPdfTools } from './tools.js'\n\nexport const name = 'dsh-pdf-reader'\n\nexport const inject = ['tools', 'subprocess', 'fs', 'timer']\n\nexport function apply(ctx) {\n  registerPdfTools(ctx)\n}\n"
    },
