      "path": "lib/tools.js",
      "content": "/**\n * dsh-pdf-reader agent-facing tools: pdf_scan / pdf_read_page / pdf_render_region.\n *\n * Each tool first resolves a Python interpreter with PyMuPDF. When the\n * environment is incomplete it returns a descriptive warning (what's missing,\n * how to fix it) and lets the agent handle it — it never hard-fails.\n *\n * NOTE: tools are built here as plain registry-ready objects rather than via\n * `defineTool` from `@deepseek-ai/dsh-tools`, so the plugin has NO runtime\n * peer import and works out of the box with `dsh plugin add link:<path>`\n * (no `npm install` needed). `ctx.tools.register()` accepts this shape.\n */\nimport { fileURLToPath } from 'node:url'\nimport path from 'node:path'\nimport { resolvePdfPython } from './python.js'\nimport { runPython } from './runner.js'\n\nconst HELPER = fileURLToPath(new URL('./pdf_helper.py', import.meta.url))\n\nexport const TOOL_CAPS = Object.freeze({ doneCapMs: 120_000, graceMs: 15_000 })\n\nfunction sessionCwd(exec) {\n  return exec?.agent?.session?.header?.cwd || process.cwd()\n}\n\nfunction absPath(p, cwd) {\n  return p && path.isAbsolute(p) ? p : path.resolve(cwd, p)\n}\n\nasync function runHelper(ctx, exec, argv, limits = TOOL_CAPS) {\n  const cwd = sessionCwd(exec)\n  const env = await resolvePdfPython(ctx.subprocess, ctx.fs, ctx.timer, cwd, exec?.signal)\n  if (!env.ready) return { ok: false, warning: env.warning, missing: env.missing }\n\n  const out = await runPython(\n    ctx.subprocess, ctx.timer,\n    [env.interpreter, HELPER, ...argv],\n    cwd, limits, exec?.signal,\n  )\n  if (out.timedOut) return { ok: false, error: `PDF helper timed out after ${limits.doneCapMs}ms; the process tree was terminated.` }\n  if (out.exitCode !== 0) return { ok: false, error: (out.stderr || 'PDF helper failed').trim() }\n  try {\n    return JSON.parse(out.stdout)\n  } catch {\n    return { ok: false, error: 'PDF helper returned malformed JSON: ' + out.stdout.slice(0, 200) }\n  }\n}\n\nfunction renderResult(_args, value) {\n  if (value && typeof value === 'object') {\n    const text = value.error || value.warning\n      ? `⚠ ${value.error || value.warning}`\n      : JSON.stringify(value, null, 2)\n    return [{ type: 'text', text }]\n  }\n  return [{ type: 'text', text: String(value) }]\n}\n\n/** Build a registry-ready tool definition (matches the shape defineTool returns). */\nfunction tool({ name, description, parameters, timeoutMs, execute }) {\n  return {\n    name,\n    description,\n    parameters,\n    output: { schema: { type: 'object', additionalProperties: true }, render: renderResult },\n    timeoutMs,\n    execute,\n  }\n}\n\nfunction objectParams(properties, required) {\n  return { type: 'object', properties, required, additionalProperties: false }\n}\n\nexport function registerPdfTools(ctx) {\n  ctx.tools.register(\n    tool({\n      name: 'pdf_scan',\n      description:\n        'Whole-document overview. Scan a PDF and return a per-page content profile so you can ' +\n        'plan how to read each page, BEFORE spending a render budget. For every page: textChars, ' +\n        'columns, figures (vector regions), rasterImages, tables, formulaRisk, hasGraphics, ' +\n        'hasTextLayer. Then per page use pdf_read_page (mode=\"mixed\" for full coverage: preview ' +\n        '+ text + auto region crops) and pdf_render_region for targeted zooms. Requires Python ' +\n        'with pymupdf.',\n      parameters: objectParams({\n        pdf_path: { type: 'string', description: 'Absolute or session-relative path of the PDF.' },\n        pages: { type: 'string', description: 'Optional comma-separated page list, e.g. \"2,5-8\". Default: all pages.' },\n      }, ['pdf_path']),\n      timeoutMs: 120_000,\n      async execute(args, exec) {\n        const a = args ?? {}\n        const cwd = sessionCwd(exec)\n        if (!a.pdf_path) return { ok: false, error: 'pdf_path is required' }\n        const argv = ['scan', absPath(a.pdf_path, cwd)]\n        if (a.pages) argv.push('--pages', String(a.pages))\n        return runHelper(ctx, exec, argv)\n      },\n    }),\n  )\n\n  ctx.tools.register(\n    tool({\n      name: 'pdf_read_page',\n      description:\n        'Read one page of a PDF. Recommended per-page workflow: ' +\n        '(1) PREVIEW — mode=\"mixed\" returns a low-res full-page render (fullPage) plus the ' +\n        'extracted text, so you see the whole layout (formulas, table gridlines, figure ' +\n        'placement) without burning the token budget; ' +\n        '(2) CONTENT — mode=\"mixed\" also auto-detects every figure/table region and renders it ' +\n        'as a high-DPI PNG. All PNGs are saved to <cwd>/.dsh-pdf-reader and returned only as ' +\n        'PATHS (never inlined), so long/heavy content stays in the cache, not in your context — ' +\n        'read them via read_image; ' +\n        '(3) REFINE — if a specific area is still too small or was not auto-cropped (an ' +\n        'uncropped formula, a crowded table cell, a sub-figure), zoom it with pdf_render_region ' +\n        'on the exact [x0,y0,x1,y1] bbox you read off the fullPage preview. ' +\n        'For a whole-document overview first run pdf_scan. mode=\"auto\" returns just the largest ' +\n        'figure/table image (or the text) per the page profile; mode=\"text\" forces extraction; ' +\n        'mode=\"render\" forces a render of an explicit region. Needs Python+pymupdf.',\n      parameters: objectParams({\n        pdf_path: { type: 'string', description: 'Absolute or session-relative PDF path.' },\n        page: { type: 'number', description: '1-based page number to read.' },\n        mode: { type: 'string', description: '\"auto\" (default), \"text\", \"mixed\", or \"render\".', enum: ['auto', 'text', 'mixed', 'render'] },\n        dpi: { type: 'number', description: 'Optional DPI override for a render; default fills the budget.' },\n        region: { type: 'array', description: '[x0,y0,x1,y1] in points, for mode=render.', items: { type: 'number' } },\n      }, ['pdf_path', 'page']),\n      timeoutMs: 120_000,\n      async execute(args, exec) {\n        const a = args ?? {}\n        const cwd = sessionCwd(exec)\n        if (!a.pdf_path || !a.page) return { ok: false, error: 'pdf_path and page are required' }\n        const argv = ['read', absPath(a.pdf_path, cwd), String(a.page), '--out-dir', path.join(cwd, '.dsh-pdf-reader')]\n        if (a.mode) argv.push('--mode', a.mode)\n        if (a.dpi) argv.push('--dpi', String(a.dpi))\n        if (Array.isArray(a.region) && a.region.length === 4) argv.push('--region', ...a.region.map(String))\n        return runHelper(ctx, exec, argv)\n      },\n    }),\n  )\n\n  ctx.tools.register(\n    tool({\n      name: 'pdf_render_region',\n      description:\n        'Targeted high-res render of one [x0,y0,x1,y1] bbox (in points) on a page — the REFINE ' +\n        'step. After the low-res full-page preview and auto region crops, zoom any area that is ' +\n        'still too small or ambiguous (an uncropped formula, a crowded table cell, a sub-figure) ' +\n        'by rendering the exact bbox at ~800x800 budget DPI. The PNG is saved to ' +\n        '<cwd>/.dsh-pdf-reader and returned as a PATH — read it with read_image. ' +\n        'Pull the bbox from pdf_scan or from the fullPage preview. Needs Python+pymupdf.',\n      parameters: objectParams({\n        pdf_path: { type: 'string', description: 'Absolute or session-relative PDF path.' },\n        page: { type: 'number', description: '1-based page number.' },\n        region: { type: 'array', description: '[x0,y0,x1,y1] in points.', items: { type: 'number' } },\n        dpi: { type: 'number', description: 'Optional DPI override; default fills the budget.' },\n      }, ['pdf_path', 'page', 'region']),\n      timeoutMs: 120_000,\n      async execute(args, exec) {\n        const a = args ?? {}\n        const cwd = sessionCwd(exec)\n        if (!a.pdf_path || !a.page || !Array.isArray(a.region) || a.region.length !== 4) {\n          return { ok: false, error: 'pdf_path, page, and region [x0,y0,x1,y1] are required' }\n        }\n        const argv = ['render', absPath(a.pdf_path, cwd), String(a.page), ...a.region.map(String), '--out-dir', path.join(cwd, '.dsh-pdf-reader')]\n        if (a.dpi) argv.push('--dpi', String(a.dpi))\n        return runHelper(ctx, exec, argv)\n      },\n    }),\n  )\n}\n"
    },
    {
      "path": "lib/python.js",
      "content": "/**\n * Python + PyMuPDF resolution for dsh-pdf-reader.\n *\n * Resolution is ordered and module-aware, matching the user's intent:\n *   1. try the \"main\" Python on PATH (the one the harness/agent is running\n *      against) — if it can `import pymupdf`, use it;\n *   2. otherwise try python3 / py, then the project-local venvs (.venv/venv/env)\n *      under the session cwd — first one that can `import pymupdf` wins;\n *   3. if none can, return a structured `warning` naming exactly what is\n *      missing and the command that would fix it, and let the agent decide.\n *\n * (Unlike a CLI tool such as graphlint, we must resolve a *Python interpreter*\n *  AND verify the *module* imports — pymupdf is a library, not an executable.)\n */\nimport { join } from 'node:path'\nimport { runPython } from './runner.js'\n\nconst VENV_BASES = ['.venv', 'venv', 'env']\nconst WINDOWS = { bin: 'Scripts', exe: 'python.exe' }\nconst POSIX = { bin: 'bin', exe: 'python' }\n\n/** Ordered, de-duplicated candidate interpreter paths. */\nexport async function listInterpreters(subprocess, fs, cwd) {\n  const seen = new Set()\n  const out = []\n  const push = (p) => {\n    if (p && !seen.has(p)) {\n      seen.add(p)\n      out.push(p)\n    }\n  }\n  const rels = process.platform === 'win32' ? WINDOWS : POSIX\n\n  // 1) the explicitly activated venv (highest priority) — the user is using\n  //    this Python right now; if it has pymupdf it is the intended target.\n  if (process.env.VIRTUAL_ENV) {\n    push(join(process.env.VIRTUAL_ENV, rels.bin, rels.exe))\n  }\n\n  // 2) main Python on PATH (activator / harness runtime)\n  for (const cmd of ['python', 'python3', 'py']) {\n    try {\n      const exe = await subprocess.resolveExecutable(cmd)\n      push(exe)\n    } catch {\n      /* PATH lookup failed */\n    }\n  }\n\n  // 3) project-local virtualenv interpreters under the session cwd\n  for (const base of VENV_BASES) {\n    push(join(cwd, base, rels.bin, rels.exe))\n  }\n  return out\n}\n\n/**\n * Run `interpreter -c <probe>` and return {ok, version} for an import probe.\n */\nexport async function probeImport(subprocess, timer, interpreter, module, signal) {\n  const out = await runPython(\n    subprocess, timer,\n    [`${interpreter}`, '-c', `import ${module}, sys; print(getattr(${module}, '__version__', '?'))`],\n    process.cwd(),\n    { doneCapMs: 20_000 },\n    signal,\n  )\n  if (out.exitCode === 0) return { ok: true, version: out.stdout.trim() }\n  return { ok: false, stderr: out.stderr.trim() }\n}\n\nfunction buildWarning(candidates) {\n  const w = ['PDF reading is not available — no Python interpreter with `pymupdf` was found.']\n  if (candidates.length) w.push(`Tried: ${candidates.join(', ')}.`)\n  else w.push('No Python interpreter was found on PATH or in this project.')\n  w.push('To enable, either:')\n  w.push('  - install pymupdf into your main Python:  python -m pip install pymupdf')\n  w.push('  - or create a project venv:  python -m venv .venv && .venv\\\\Scripts\\\\python.exe -m pip install pymupdf')\n  w.push('Re-run this tool once a Python with pymupdf is available.')\n  return w.join('\\n')\n}\n\n/** Resolve a ready interpreter+pymupdf, or a clear actionable warning. */\nexport async function resolvePdfPython(subprocess, fs, timer, cwd, signal) {\n  const candidates = await listInterpreters(subprocess, fs, cwd)\n  for (const interpreter of candidates) {\n    const pym = await probeImport(subprocess, timer, interpreter, 'pymupdf', signal)\n    if (pym.ok) {\n      const four = await probeImport(subprocess, timer, interpreter, 'pymupdf4llm', signal)\n      return { ready: true, interpreter, pymupdf: true, pymupdf4llm: four.ok }\n    }\n  }\n  // figure out which was missing (python vs pymupdf) for a clearer message\n  return {\n    ready: false,\n    warning: buildWarning(candidates),\n    missing: ['a Python interpreter with the `pymupdf` package'],\n    interpreter: candidates[0] ?? null,\n  }\n}\n"
    },
