      "path": "lib/runner.js",
      "content": "/**\n * Spawn a Python helper invocation and collect its stdio.\n *\n * Hardening (mirrors dsh-graphlint's runner):\n *  - force UTF-8 via PYTHONIOENCODING so a localized code page cannot garble\n *    the JSON payload;\n *  - wire the caller's AbortSignal so a cooperative timeout terminates the tree;\n *  - cap the exit wait so a wedged process cannot hang the tool turn;\n *  - never shell-interpret argv (plain argv array).\n */\n\nexport const DEFAULT_LIMITS = Object.freeze({ doneCapMs: 120_000, graceMs: 15_000 })\n\nexport function runPython(subprocess, timer, argv, cwd, limits = DEFAULT_LIMITS, signal) {\n  // Merge partial limits with the defaults: callers may pass only `doneCapMs`\n  // (e.g. the import probe in python.js). `subprocess.spawn` validates that\n  // `graceMs` is a positive finite number, so an omitted field (undefined)\n  // would be rejected — fill it from the defaults instead of forwarding it.\n  const l = { ...DEFAULT_LIMITS, ...(limits || {}) }\n  const handle = subprocess.spawn({\n    argv,\n    cwd,\n    stdio: {\n      stdin: 'ignore',\n      stdout: { maxBytes: 8 * 1024 * 1024 },\n      stderr: { maxBytes: 512 * 1024 },\n    },\n    graceMs: l.graceMs,\n    signal,\n    env: { PYTHONIOENCODING: 'utf-8', PYTHONDONTWRITEBYTECODE: '1' },\n  })\n  const done = new Promise((resolve) => {\n    const timeout = timer.timeout(() => {\n      handle.terminate()\n      resolve({ exitCode: null, stdout: '', stderr: '', timedOut: true })\n    }, l.doneCapMs)\n    handle.done.then(\n      (outcome) => {\n        timeout()\n        resolve({\n          exitCode: outcome.exitCode,\n          stdout: handle.collected?.stdout?.readFrom(0).text ?? '',\n          stderr: handle.collected?.stderr?.readFrom(0).text ?? '',\n          timedOut: false,\n        })\n      },\n      () => {\n        timeout()\n        resolve({ exitCode: null, stdout: '', stderr: '', timedOut: false })\n      },\n    )\n  })\n  return done\n}\n"
    },
    {
      "path": "lib/pdf_helper.py",
      "content": "# -*- coding: utf-8 -*-\n\"\"\"dsh-pdf-reader engine (PyMuPDF).\n\nAgent-facing subcommands (JSON to stdout):\n  scan   <pdf>                              -> per-page content profile\n  read   <pdf> <page> [mode|auto] [dpi] [region...] -> text OR rendered region path\n  render <pdf> <page> <x0 y0 x1 y1> [dpi]   -> rendered crop path\n\nDesign notes:\n  * \"content completeness first\": candidate figure/table/math regions are\n    rendered to fill the model's ~640k-pixel budget (DeepSeek ~800x800 /\n    384-token), so nothing legible is lost inside the budget; the crop is\n    token-optimal because it is rendered AT the budget, not beyond it.\n  * Figures are located by clustering vector drawing ops (get_drawings) plus\n    raster placement rects (get_image_rects). Tables are ALSO drawn with\n    vector rules, so a table region shows up as a drawing cluster too; this\n    avoids find_tables' well-known false positives on plot grids.\n  * Math is detected via math/symbol font names (cmmi/cmsy/Type3/STIX/...)\n    plus a LaTeX producer (pdfTeX/LaTeX), since the extracted text layer\n    garbles formulas.\n\"\"\"\nimport argparse\nimport contextlib\nimport io\nimport json\nimport math\nimport os\nimport sys\n\nPT2IN = 1.0 / 72.0\n# DeepSeek per-image budget (~800x800-equivalent / 384 tokens); DSH's\n# DEFAULT_REQUEST_IMAGE_PIXEL_BUDGET is also 640000.\nPIXEL_BUDGET = 640_000\nMATH_FONT_RE = (\"cmmi\", \"cmsy\", \"cmmib\", \"cmex\", \"msam\", \"msbm\", \"type3\",\n                \"stix\", \"mtpro\", \"xits\", \"euler\", \"fourier\", \"txapp\", \"math\")\n\n\ndef _cluster_rects(rects, gap=8.0, min_area=400.0):\n    \"\"\"Union nearby rects into clusters (vector figure/table regions).\"\"\"\n    import pymupdf as m\n    rects = [m.Rect(r) for r in rects]\n    changed = True\n    while changed:\n        changed = False\n        out = []\n        while rects:\n            cur = rects.pop()\n            merged = False\n            for idx, existing in enumerate(out):\n                grow = m.Rect(cur)\n                grow.x0 -= gap; grow.y0 -= gap; grow.x1 += gap; grow.y1 += gap\n                if grow.intersects(existing):\n                    merged_rect = m.Rect(existing)\n                    merged_rect.include_rect(cur)\n                    out[idx] = merged_rect\n                    merged = True; changed = True\n                    break\n            if not merged:\n                out.append(cur)\n        rects = out\n    return [r for r in rects if not r.is_empty and r.get_area() > min_area]\n\n\ndef _columns(page):\n    \"\"\"Best-effort column count from text block left edges (2-col detection).\"\"\"\n    try:\n        blocks = page.get_text(\"blocks\")\n    except Exception:\n        return 1\n    xs = sorted(round(b[0]) for b in blocks if len(b) >= 5 and b[6] == 0)\n    if not xs:\n        return 1\n    xs = sorted(set(xs))\n    gaps = [(xs[i + 1] - xs[i], xs[i], xs[i + 1]) for i in range(len(xs) - 1)]\n    if not gaps:\n        return 1\n    big = max(gaps) if gaps else (0, 0, 0)\n    # a big horizontal gap in block-left edges => separate columns\n    return 2 if big[0] > 0.20 * page.rect.width else 1\n\n\ndef _math_fonts(page):\n    names = []\n    try:\n        for f in page.get_fonts():\n            name = ((f[3] or \"\") + \" \" + (f[4] or \"\")).strip()\n            if name:\n                names.append(name)\n    except Exception:\n        pass\n    low = \" \".join(names).lower()\n    hit = sorted({n for n in names if any(k in n.lower() for k in MATH_FONT_RE)})\n    return {\"fonts\": names, \"mathFonts\": hit, \"producer_latex\": None}\n\n\ndef _text_stats(page):\n    text = \"\"\n    try:\n        text = page.get_text(\"text\")\n    except Exception:\n        pass\n    chars = len(text)\n    # replacement + PUA counts are a weak proxy; math/symbol fonts are the\n    # authoritative signal, so we report both but route on fonts + figures.\n    pua = sum(1 for c in text if 0xE000 <= ord(c) <= 0xF8FF or ord(c) == 0xFFFD)\n    return {\"textChars\": chars, \"mojibakeCount\": pua,\n            \"hasTextLayer\": chars > 0}\n\n\ndef scan_page(doc, page_num):\n    page = doc[page_num - 1]\n    pr = page.rect\n    page_area = pr.get_area() or 1.0\n    # \"meaningful graphics\" = a cluster covering >=1% of the page; this skips\n    # small logos, CC badges, and decorative rules that would otherwise trigger\n    # a pointless render of a mostly-text page.\n    mini = 0.01 * page_area\n    img_rects = []\n    try:\n        for img in page.get_images(full=True):\n            xref = img[0]\n            for r in page.get_image_rects(xref):\n                if r.get_area() >= mini:\n                    img_rects.append(list(r))\n    except Exception:\n        pass\n    draw_clusters = []\n    try:\n        draws = page.get_drawings()\n        # include THIN connector lines/arrows too: they belong to their figure.\n        # filter on the LARGER dimension, not the area: a connector arrow is a\n        # zero-width or zero-height line whose rect area is ~0, but it is the\n        # very element that bridges a figure's components. Dropping it (as an\n        # area filter would) splits one flowchart into a big cluster plus a tiny\n        # orphan that falls below min_area and is lost — clipping the bbox.\n        # cluster first (proximity merges lines into their figure), then keep\n        # only clusters >=1% of the page (drops logos/decorative rules).\n        all_items = [d[\"rect\"] for d in draws\n                     if max(d[\"rect\"].width, d[\"rect\"].height) > 2.0]\n        draw_clusters = [list(r) for r in _cluster_rects(all_items, gap=10.0, min_area=mini)]\n    except Exception:\n        pass\n\n    tables = []\n    try:\n        for t in page.find_tables().tables:\n            tables.append({\"bbox\": list(t.bbox), \"rows\": t.row_count,\n                           \"cols\": t.col_count})\n    except Exception:\n        pass\n\n    fs = _math_fonts(page)\n    ts = _text_stats(page)\n    producer = (doc.metadata or {}).get(\"producer\", \"\") or \"\"\n    latex = (\"pdftex\" in producer.lower() or \"latex\" in producer.lower()\n             or bool(fs[\"mathFonts\"]))\n\n    return {\n        \"page\": page_num,\n        \"size\": [round(pr.width, 1), round(pr.height, 1)],\n        \"columns\": _columns(page),\n        \"figures\": draw_clusters,\n        \"rasterImages\": img_rects,\n        \"tables\": tables,\n        \"math\": {\"fonts\": fs[\"fonts\"], \"mathFonts\": fs[\"mathFonts\"],\n                 \"likelyLatex\": latex},\n        # this page has a visual element text extraction cannot convey\n        \"hasGraphics\": bool(draw_clusters or img_rects or tables),\n        # text extraction may still garble stacked formulas; flag it so the\n        # agent can choose to render a specific equation region if exact\n        # structure is needed (pymupdf extracts inline math well, though).\n        \"formulaRisk\": latex and bool(fs[\"mathFonts\"]),\n        \"text\": ts,\n    }\n\n\ndef area_dpi(w_pt, h_pt, budget=PIXEL_BUDGET):\n    return 72.0 * (budget / max(1.0, w_pt * h_pt)) ** 0.5\n\n\ndef _largest(rects):\n    if not rects:\n        return None\n    import pymupdf as m\n    return max((m.Rect(r) for r in rects), key=lambda r: r.get_area())\n\n\ndef best_region(profile):\n    \"\"\"Pick the crop that preserves the most content: largest raster or the\n    largest vector cluster (covers figures AND tables). Returns (bbox, label).\"\"\"\n    cands = []\n    for r in profile.get(\"figures\", []):\n        cands.append((r, \"figure\"))\n    for r in profile.get(\"rasterImages\", []):\n        cands.append((r, \"raster\"))\n    for t in profile.get(\"tables\", []):\n        cands.append((t[\"bbox\"], \"table\"))\n    if not cands:\n        return None, None\n    import pymupdf as m\n    cands = [(m.Rect(c), label) for c, label in cands]\n    return max(cands, key=lambda c: c[0].get_area())\n\n\ndef cmd_scan(args):\n    import pymupdf as m\n    doc = m.open(args.pdf)\n    wanted = _page_selector(args.pages, doc.page_count)\n    out = {\n        \"ok\": True,\n        \"pdf\": args.pdf,\n        \"producer\": (doc.metadata or {}).get(\"producer\", \"\"),\n        \"pages\": doc.page_count,\n        \"pageSize\": [round(doc[0].rect.width, 1), round(doc[0].rect.height, 1)],\n        \"pages_profile\": [scan_page(doc, i) for i in wanted],\n    }\n    doc.close()\n    return out\n\n\ndef _page_selector(spec, total):\n    \"\"\"Parse '2,5-8' into a sorted 1-based page list.\"\"\"\n    pages = []\n    if not spec:\n        return list(range(1, total + 1))\n    for part in str(spec).split(\",\"):\n        part = part.strip()\n        if not part:\n            continue\n        if \"-\" in part:\n            lo, hi = part.split(\"-\", 1)\n            pages.extend(range(int(lo), int(hi) + 1))\n        else:\n            pages.append(int(part))\n    return [p for p in pages if 1 <= p <= total]\n\n\ndef cmd_render(args):\n    import pymupdf as m\n    doc = m.open(args.pdf)\n    page = doc[args.page - 1]\n    rect = m.Rect(args.region)\n    if rect.is_empty or rect.get_area() <= 0:\n        rect = page.rect\n    dpi = args.dpi or round(area_dpi(rect.width, rect.height))\n    pm = page.get_pixmap(clip=rect, matrix=m.Matrix(dpi / 72.0, dpi / 72.0))\n    os.makedirs(args.out_dir, exist_ok=True)\n    path = os.path.join(args.out_dir,\n                        f\"{os.path.basename(args.pdf)}-p{args.page}-{int(rect.x0)}x{int(rect.y0)}.png\")\n    pm.save(path)\n    doc.close()\n    return {\"ok\": True, \"path\": path, \"bbox\": list(rect), \"dpi\": dpi,\n            \"width\": pm.width, \"height\": pm.height,\n            \"pixels\": pm.width * pm.height, \"budget\": PIXEL_BUDGET,\n            \"scaled\": (pm.width * pm.height > PIXEL_BUDGET)}\n\n\ndef _render_region_image(page, rect, out_dir, pdf_base, page_num, dpi_override=None):\n    \"\"\"Render one rect at the area-budget dpi and save a 